-- ROLLBACK PLAN: forward-only. Non-prod: ALTER TABLE file_objects DROP COLUMN source_type, DROP COLUMN tags, DROP COLUMN sensitivity; ALTER TABLE jobs DROP COLUMN content_labels.
--   The enum value job_status 'QUARANTINED' cannot be dropped in place; to remove it, first move such jobs to another status, then recreate the type
--   in a new forward migration. Prod: ship a new forward migration; do not edit this file. Dropping the columns loses upload tags and content labels.
-- Group: upload tagging and content classification (file-ingestion).
--   file_objects.tags / sensitivity: client-supplied at upload creation (tenant comes from the token, never the body).
--   file_objects.source_type: processing profile name from the code-registered table in internal/profile (unknown input is stored as 'unknown').
--   jobs.content_labels: classifier output {label: {count, fields[]}}; counts and column/field NAMES only, never matched values.
--   job_status QUARANTINED: terminal state for a file job held back by the credentials policy; nothing was written to the sink.
-- RLS: both tables already have tenant RLS (0004); new columns are covered by the same policies.

ALTER TYPE job_status ADD VALUE IF NOT EXISTS 'QUARANTINED';

ALTER TABLE file_objects
  ADD COLUMN source_type text  NOT NULL DEFAULT 'unknown' CHECK (source_type ~ '^[a-z][a-z0-9_]{0,31}$'),
  ADD COLUMN tags        jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(tags) = 'object'),
  ADD COLUMN sensitivity text  NOT NULL DEFAULT 'internal' CHECK (sensitivity IN ('public','internal','restricted'));
CREATE INDEX file_objects_sensitivity_ix ON file_objects (tenant_id, sensitivity, created_at DESC);
CREATE INDEX file_objects_tags_gin ON file_objects USING gin (tags jsonb_path_ops);

ALTER TABLE jobs
  ADD COLUMN content_labels jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(content_labels) = 'object');
